onumber\ &=& \sum_{t=1}^{|B|}{H(Y_{\Psi_t}|Y^{\Psi_{t-1}})} 
onumber\ &=& \sum_{t=1}^{|B|}{\sum_{y^{\Psi_{t-1}}}H(Y_{\Psi_t}|Y^{\Psi_{t-1}}=y^{\Psi_{t-1}})P(y^{\Psi_{t-1}})} 
onumber\ & \stackrel{(b)}{\leq} & \sum_{t=1}^{|B|}{\sum_{y^{\Psi_{t-1}}}\zeta\left(E_{Q_B}\left\{l\left(X_{\Psi_t},	ilde{F}_{t}(y^{\Psi_{t-1}},Y_{\Psi_t})ight)|Y^{\Psi_{t-1}}=y^{\Psi_{t-1}}ight\}ight)P(y^{\Psi_{t-1}})} 
